<script setup>
import {ref,computed,onMounted} from 'vue';import {useData} from '../stores/data';import Notice from '../components/Notice.vue';const store=useData();const form=ref({name:'',id:'',phone:'',zip:''}),search=ref(''),message=ref(''),error=ref(''),busy=ref(false);const filtered=computed(()=>store.students.filter(s=>(s.name+' '+s.id).toLowerCase().includes(search.value.toLowerCase())));onMounted(()=>store.refresh().catch(e=>error.value=e.message));async function add(){busy.value=true;message.value='';error.value='';try{await store.request('/students',{method:'POST',body:JSON.stringify(form.value)});form.value={name:'',id:'',phone:'',zip:''};await store.refresh();message.value='Student added successfully'}catch(e){error.value=e.message}finally{busy.value=false}}async function remove(s){if(!confirm('Delete '+s.name+' and their enrollments?'))return;error.value='';message.value='';try{await store.request('/students/'+s._id,{method:'DELETE'});await store.refresh();message.value='Student deleted'}catch(e){error.value=e.message}}</script>
<template><div class="eyebrow">ACADEMIC RECORDS</div><h1>Students</h1><p class="subtitle">Manage student profiles and contact information.</p><div class="stats"><div class="stat"><span>Total students</span><strong>{{store.students.length}}</strong></div></div><div class="two-col"><section class="panel"><div class="panel-heading"><h2>Add a student</h2><p>Enter the student's details below.</p></div><form @submit.prevent="add" class="form"><label>Full name<input v-model.trim="form.name" placeholder="e.g. John Smith" required></label><label>Student ID<input v-model.trim="form.id" placeholder="e.g. 1001" required></label><label>Phone number<input v-model.trim="form.phone" placeholder="e.g. 555-1234" required></label><label>ZIP code<input v-model.trim="form.zip" placeholder="e.g. 77001" required></label><button :disabled="busy" class="primary">{{busy?'Saving…':'+ Add student'}}</button></form><Notice :message="error" type="error"/><Notice :message="message"/></section><section class="panel"><div class="panel-heading"><h2>Student directory</h2><p>Search and manage records.</p></div><input v-model="search" class="search" aria-label="Search students" placeholder="Search by name or student ID"><div v-if="store.loading" class="empty">Loading students…</div><div v-else-if="!filtered.length" class="empty">No students found.</div><div v-for="s in filtered" :key="s._id" class="record"><div class="avatar">{{s.name.charAt(0).toUpperCase()}}</div><div class="record-body"><strong>{{s.name}}</strong><span>ID {{s.id}} · {{s.phone}}</span><small>ZIP {{s.zip}}</small></div><button class="danger" :aria-label="'Delete '+s.name" @click="remove(s)">Delete</button></div></section></div></template>